    public function run(): void
    {
        $this->overview();
        $results = [];
        foreach ($this->settings['runs'] as $definition) {
            $r = $definition
            + [
                'status' => 'FAIL',
                'reason' => null,
                'paths' => null,
                'high' => 0,
                'generated' => null,
                'budget' => new Budget($this->settings['ll_budget']),
                'specific' => [],
                'trace' => [],
                'end' => '',
            ];
            if ($r['solver'] === 'PP')
                $this->solvePP($r);
            elseif ($r['solver'] === 'WHCA')
                $this->solveWHCA($r);
            else
                $this->solveCBS($r);
            if ($r['status'] === 'OK') {
                $r['metrics'] = $this->metrics($r['paths'], $r['function']);
                $r['validation'] = $this->validate($r['paths']);
                $r['execution'] = $this->delayedExecution($r['paths']);
            }
            $results[] = $r;
        }
        $this->write($results);
    }
function position(array $path, int $time): int
{
    return $path[min($time, count($path) - 1)];
}
function conflicts(array $paths): array
{
    $result = [];
    $horizon = max(array_map(fn($p) => count($p) - 1, $paths));
    $n = count($paths);
    for ($t = 1; $t <= $horizon; ++$t)
        for ($a = 0; $a < $n; ++$a)
            for ($b = $a + 1; $b < $n; ++$b) {
                $ca = position($paths[$a], $t);
                $cb = position($paths[$b], $t);
                if ($ca === $cb)
                    $result[] = ['kind' => 'vertex', 'time' => $t, 'a' => $a, 'b' => $b, 'cell' => $ca];
                elseif ($ca === position($paths[$b], $t - 1) && $cb === position($paths[$a], $t - 1))
                    $result[] = [
                        'kind' => 'edge',
                        'time' => $t,
                        'a' => $a,
                        'b' => $b,
                        'u' => position($paths[$a], $t - 1),
                        'v' => $ca,
                    ];
            }
    return $result;
}
function planCost(array $paths, string $function): int
{
    $lengths = array_map(fn($p) => count($p) - 1, $paths);
    return $function === 'SOC' ? array_sum($lengths) : max($lengths);
}
function tryOrder(
    Grid $grid,
    array $agents,
    array $distances,
    int $horizon,
    array $order,
    Budget $budget,
): array {
    $p = new Prohibitions();
    $paths = $attempts = [];
    foreach ($order as $i) {
        try {
            [$path, $expanded] = lowSearch(
                $grid,
                $agents[$i],
                $distances[$i],
                $agents[$i]['start'],
                0,
                $p,
                $horizon,
                $budget,
            );
        } catch (BudgetExceeded) {
            return [null, $attempts, 'll_budget'];
        }
        $attempts[] = ['agent' => $i, 'path' => $path, 'expansions' => $expanded];
        if ($path === null)
            return [null, $attempts, $i];
        $paths[$i] = $path;
        $p->reserve($path, 0, true);
    }
    ksort($paths, SORT_NUMERIC);
    return [array_values($paths), $attempts, null];
}
